INSERT INTO "modelos_sessao" ("id","codigo","nome","tipo","descricao","duracao_estimada","treinamento_id","ordem_no_treinamento","ativo","created_at","updated_at","deleted_at","tipo_sessao_id","tipo_aeronave","codigo_aeronave","gera_qualificacao","empresa_id","modelo_aeronave") VALUES(28,'A139-P-VFR/C1','AW139 - PERIÓDICO - 01/03: VFR CICLO 1','Treinamento Inicial','Sessão focada em manobras básicas em voo visual e emergências elétricas e de motor, em ambiente diurno VFR com cenário offshore. O objetivo é consolidar controle fino da aeronave, autorrotação completa, dual/single GEN failure, falhas de motor e panes em MGB, preparando a tripulação para situações críticas frequentes na operação offshore.',120,NULL,NULL,1,'2026-01-11 01:50:31','2026-03-11 00:41:42',NULL,9,'AW139','AW139',0,6,'AW139');
INSERT INTO "modelos_sessao" ("id","codigo","nome","tipo","descricao","duracao_estimada","treinamento_id","ordem_no_treinamento","ativo","created_at","updated_at","deleted_at","tipo_sessao_id","tipo_aeronave","codigo_aeronave","gera_qualificacao","empresa_id","modelo_aeronave") VALUES(29,'A139-P-IFR/C1','AW139 - PERIÓDICO - 02/03: IFR CICLO 1','Treinamento Inicial','Sessão IFR em IMC baixa, voltada para uso de AFCS, gestão de falhas de aviônicos e trem de pouso em ambiente de procedimentos por instrumentos. O piloto pratica controle IFR, automação, falhas de AP/AFCS/ADS/AHRS/FMS/GPS, fogo em bagageiro, pane hidráulica, servo bypass e aproximações ILS/VOR/NDB com arremetida.',120,NULL,NULL,1,'2026-01-11 01:50:31','2026-03-11 00:41:08',NULL,9,'AW139','AW139',0,6,'AW139');
INSERT INTO "modelos_sessao" ("id","codigo","nome","tipo","descricao","duracao_estimada","treinamento_id","ordem_no_treinamento","ativo","created_at","updated_at","deleted_at","tipo_sessao_id","tipo_aeronave","codigo_aeronave","gera_qualificacao","empresa_id","modelo_aeronave") VALUES(30,'A139-P-VFR/C2','AW139 - PERIÓDICO - 01/03: VFR CICLO 2','Treinamento Inicial','Sessão VFR combinando operações diurnas e noturnas com ênfase em sistema elétrico, combustível e desligamento de emergência de motor. São treinadas falhas de gerador DC, battery offline, low fuel, double fuel pump failure, EEC failure, engine shutdown de emergência, além de decolagens, pousos e autorrotação.',120,NULL,NULL,1,'2026-01-11 01:50:31','2026-03-11 00:41:54',NULL,9,'AW139','AW139',0,6,'AW139');
INSERT INTO "modelos_sessao" ("id","codigo","nome","tipo","descricao","duracao_estimada","treinamento_id","ordem_no_treinamento","ativo","created_at","updated_at","deleted_at","tipo_sessao_id","tipo_aeronave","codigo_aeronave","gera_qualificacao","empresa_id","modelo_aeronave") VALUES(31,'A139-P-IFR/C2','AW139 - PERIÓDICO - 02/03: IFR CICLO 2','Treinamento Inicial','Sessão IFR em IMC moderada, centrada em falhas de referência inercial/navegação e gerenciamento de energia elétrica. Inclui AP OFF, SAS degraded, falhas de AHRS, GPS, DU, FMS, DC bus, smoke in cockpit, navegação FMS/convencional, SID/STAR, holding e aproximações de precisão e não precisão com pane de óleo de motor.',120,NULL,NULL,1,'2026-01-11 01:50:31','2026-03-11 00:41:19',NULL,9,'AW139','AW139',0,6,'AW139');
INSERT INTO "modelos_sessao" ("id","codigo","nome","tipo","descricao","duracao_estimada","treinamento_id","ordem_no_treinamento","ativo","created_at","updated_at","deleted_at","tipo_sessao_id","tipo_aeronave","codigo_aeronave","gera_qualificacao","empresa_id","modelo_aeronave") VALUES(32,'A139-P-VFR/C3','AW139 - PERIÓDICO - 01/03: VFR CICLO 3','Treinamento Inicial','Sessão VFR sobre água com foco em falhas de rotor de cauda, controles de voo e aquecimento de baterias, em contexto de operação offshore. O treinamento cobre circuito de tráfego, autorrotação, battery overheat, engine failure offshore, falhas de tail rotor drive/control, binding dos comandos, falhas de MGB e EEC, encerrando com aproximação a heliponto.',120,NULL,NULL,1,'2026-01-11 01:50:31','2026-03-11 00:42:02',NULL,9,'AW139','AW139',0,6,'AW139');
INSERT INTO "modelos_sessao" ("id","codigo","nome","tipo","descricao","duracao_estimada","treinamento_id","ordem_no_treinamento","ativo","created_at","updated_at","deleted_at","tipo_sessao_id","tipo_aeronave","codigo_aeronave","gera_qualificacao","empresa_id","modelo_aeronave") VALUES(33,'A139-P-IFR/C3','AW139 - PERIÓDICO - 02/03: IFR CICLO 3','Treinamento Inicial','Sessão IFR avançada em IMC, priorizando MISTRIM, DU degradado e navegação complexa com múltiplas falhas simultâneas. O piloto pratica controle IFR com MISTRIM, falhas de AP, ADS, DU, GPS, smoke, anomalias de rotor e servo bypass, integrando tudo com navegação FMS/convencional, holding, ILS, VOR/NDB e arremetida.',120,NULL,NULL,1,'2026-01-11 01:50:31','2026-03-11 00:41:30',NULL,9,'AW139','AW139',0,6,'AW139');
INSERT INTO "modelos_sessao" ("id","codigo","nome","tipo","descricao","duracao_estimada","treinamento_id","ordem_no_treinamento","ativo","created_at","updated_at","deleted_at","tipo_sessao_id","tipo_aeronave","codigo_aeronave","gera_qualificacao","empresa_id","modelo_aeronave") VALUES(34,'A139-P-CHECK','AW139 - PERIÓDICO - 03/03: LOFT E CHECK FINAL',NULL,'',120,NULL,NULL,1,'2026-01-11 02:39:46','2026-03-11 00:40:58',NULL,9,'AW139','AW139',1,6,'AW139');
