INSERT INTO "auditoria_avancada_v2" ("id","tabela","acao","registro_id","dados_anteriores","dados_novos","created_at","usuario_id","ip_address","user_agent","origem") VALUES(3999,'modelos_sessao','UPDATE','29','{"id":29,"codigo":"A139-P-IFR/C1","nome":"02/03: IFR CICLO 1","tipo":"Treinamento Inicial","descricao":"","duracao_estimada":120,"treinamento_id":null,"ordem_no_treinamento":null,"ativo":1,"created_at":"2026-01-11 01:50:31","updated_at":"2026-01-11 02:27:05","deleted_at":null,"tipo_sessao_id":9,"tipo_aeronave":"AW139","codigo_aeronave":null,"gera_qualificacao":0,"empresa_id":1}','{"codigo":"A139-P-IFR/C1","nome":"02/03: IFR CICLO 1","tipo_sessao_id":9,"descricao":"Sessão IFR em IMC baixa, voltada para uso de AFCS, gestão de falhas de aviônicos e trem de pouso em ambiente de procedimentos por instrumentos. O piloto pratica controle IFR, automação, falhas de AP/AFCS/ADS/AHRS/FMS/GPS, fogo em bagageiro, pane hidráulica, servo bypass e aproximações ILS/VOR/NDB com arremetida.","duracao_estimada":120,"gera_qualificacao":0}','2026-01-11 02:35:17',NULL,NULL,NULL,'system');
INSERT INTO "auditoria_avancada_v2" ("id","tabela","acao","registro_id","dados_anteriores","dados_novos","created_at","usuario_id","ip_address","user_agent","origem") VALUES(4000,'modelos_sessao','UPDATE','30','{"id":30,"codigo":"A139-P-VFR/C2","nome":"01/03: VFR CICLO 2","tipo":"Treinamento Inicial","descricao":"","duracao_estimada":120,"treinamento_id":null,"ordem_no_treinamento":null,"ativo":1,"created_at":"2026-01-11 01:50:31","updated_at":"2026-01-11 02:30:52","deleted_at":null,"tipo_sessao_id":9,"tipo_aeronave":"AW139","codigo_aeronave":null,"gera_qualificacao":0,"empresa_id":1}','{"codigo":"A139-P-VFR/C2","nome":"01/03: VFR CICLO 2","tipo_sessao_id":9,"descricao":"Sessão VFR combinando operações diurnas e noturnas com ênfase em sistema elétrico, combustível e desligamento de emergência de motor. São treinadas falhas de gerador DC, battery offline, low fuel, double fuel pump failure, EEC failure, engine shutdown de emergência, além de decolagens, pousos e autorrotação.","duracao_estimada":120,"gera_qualificacao":0}','2026-01-11 02:36:03',NULL,NULL,NULL,'system');
INSERT INTO "auditoria_avancada_v2" ("id","tabela","acao","registro_id","dados_anteriores","dados_novos","created_at","usuario_id","ip_address","user_agent","origem") VALUES(4001,'modelos_sessao','UPDATE','31','{"id":31,"codigo":"A139-P-IFR/C2","nome":"02/03: IFR CICLO 2","tipo":"Treinamento Inicial","descricao":"","duracao_estimada":120,"treinamento_id":null,"ordem_no_treinamento":null,"ativo":1,"created_at":"2026-01-11 01:50:31","updated_at":"2026-01-11 02:29:21","deleted_at":null,"tipo_sessao_id":9,"tipo_aeronave":"AW139","codigo_aeronave":null,"gera_qualificacao":0,"empresa_id":1}','{"codigo":"A139-P-IFR/C2","nome":"02/03: IFR CICLO 2","tipo_sessao_id":9,"descricao":"Sessão IFR em IMC moderada, centrada em falhas de referência inercial/navegação e gerenciamento de energia elétrica. Inclui AP OFF, SAS degraded, falhas de AHRS, GPS, DU, FMS, DC bus, smoke in cockpit, navegação FMS/convencional, SID/STAR, holding e aproximações de precisão e não precisão com pane de óleo de motor.","duracao_estimada":120,"gera_qualificacao":0}','2026-01-11 02:36:28',NULL,NULL,NULL,'system');
