INSERT INTO "auditoria_avancada_v2" ("id","tabela","acao","registro_id","dados_anteriores","dados_novos","created_at","usuario_id","ip_address","user_agent","origem") VALUES(5061,'modelos_sessao','UPDATE','29','{"id":29,"codigo":"A139-P-IFR/C1","nome":"02/03: IFR CICLO 1","tipo":"Treinamento Inicial","descricao":"Sessão IFR em IMC baixa, voltada para uso de AFCS, gestão de falhas de aviônicos e trem de pouso em ambiente de procedimentos por instrumentos. O piloto pratica controle IFR, automação, falhas de AP/AFCS/ADS/AHRS/FMS/GPS, fogo em bagageiro, pane hidráulica, servo bypass e aproximações ILS/VOR/NDB com arremetida.","duracao_estimada":120,"treinamento_id":null,"ordem_no_treinamento":null,"ativo":1,"created_at":"2026-01-11 01:50:31","updated_at":"2026-02-28 01:47:45","deleted_at":null,"tipo_sessao_id":9,"tipo_aeronave":"AW139","codigo_aeronave":"AW139","gera_qualificacao":0,"empresa_id":6,"modelo_aeronave":"AW139"}','{"codigo":"A139-P-IFR/C1","nome":"AW139 - PERIÓDICO - 02/03: IFR CICLO 1","tipo_sessao_id":9,"descricao":"Sessão IFR em IMC baixa, voltada para uso de AFCS, gestão de falhas de aviônicos e trem de pouso em ambiente de procedimentos por instrumentos. O piloto pratica controle IFR, automação, falhas de AP/AFCS/ADS/AHRS/FMS/GPS, fogo em bagageiro, pane hidráulica, servo bypass e aproximações ILS/VOR/NDB com arremetida.","duracao_estimada":120,"gera_qualificacao":0}','2026-03-11 00:41:08',NULL,NULL,NULL,'system');
