INSERT INTO "auditoria_avancada_v2" ("id","tabela","acao","registro_id","dados_anteriores","dados_novos","created_at","usuario_id","ip_address","user_agent","origem") VALUES(5063,'modelos_sessao','UPDATE','31','{"id":31,"codigo":"A139-P-IFR/C2","nome":"02/03: IFR CICLO 2","tipo":"Treinamento Inicial","descricao":"Sessão IFR em IMC moderada, centrada em falhas de referência inercial/navegação e gerenciamento de energia elétrica. Inclui AP OFF, SAS degraded, falhas de AHRS, GPS, DU, FMS, DC bus, smoke in cockpit, navegação FMS/convencional, SID/STAR, holding e aproximações de precisão e não precisão com pane de óleo de motor.","duracao_estimada":120,"treinamento_id":null,"ordem_no_treinamento":null,"ativo":1,"created_at":"2026-01-11 01:50:31","updated_at":"2026-02-28 01:47:45","deleted_at":null,"tipo_sessao_id":9,"tipo_aeronave":"AW139","codigo_aeronave":"AW139","gera_qualificacao":0,"empresa_id":6,"modelo_aeronave":"AW139"}','{"codigo":"A139-P-IFR/C2","nome":"AW139 - PERIÓDICO - 02/03: IFR CICLO 2","tipo_sessao_id":9,"descricao":"Sessão IFR em IMC moderada, centrada em falhas de referência inercial/navegação e gerenciamento de energia elétrica. Inclui AP OFF, SAS degraded, falhas de AHRS, GPS, DU, FMS, DC bus, smoke in cockpit, navegação FMS/convencional, SID/STAR, holding e aproximações de precisão e não precisão com pane de óleo de motor.","duracao_estimada":120,"gera_qualificacao":0}','2026-03-11 00:41:19',NULL,NULL,NULL,'system');
INSERT INTO "auditoria_avancada_v2" ("id","tabela","acao","registro_id","dados_anteriores","dados_novos","created_at","usuario_id","ip_address","user_agent","origem") VALUES(5064,'modelos_sessao','UPDATE','33','{"id":33,"codigo":"A139-P-IFR/C3","nome":"02/03: IFR CICLO 3","tipo":"Treinamento Inicial","descricao":"Sessão IFR avançada em IMC, priorizando MISTRIM, DU degradado e navegação complexa com múltiplas falhas simultâneas. O piloto pratica controle IFR com MISTRIM, falhas de AP, ADS, DU, GPS, smoke, anomalias de rotor e servo bypass, integrando tudo com navegação FMS/convencional, holding, ILS, VOR/NDB e arremetida.","duracao_estimada":120,"treinamento_id":null,"ordem_no_treinamento":null,"ativo":1,"created_at":"2026-01-11 01:50:31","updated_at":"2026-02-28 01:47:45","deleted_at":null,"tipo_sessao_id":9,"tipo_aeronave":"AW139","codigo_aeronave":"AW139","gera_qualificacao":0,"empresa_id":6,"modelo_aeronave":"AW139"}','{"codigo":"A139-P-IFR/C3","nome":"AW139 - PERIÓDICO - 02/03: IFR CICLO 3","tipo_sessao_id":9,"descricao":"Sessão IFR avançada em IMC, priorizando MISTRIM, DU degradado e navegação complexa com múltiplas falhas simultâneas. O piloto pratica controle IFR com MISTRIM, falhas de AP, ADS, DU, GPS, smoke, anomalias de rotor e servo bypass, integrando tudo com navegação FMS/convencional, holding, ILS, VOR/NDB e arremetida.","duracao_estimada":120,"gera_qualificacao":0}','2026-03-11 00:41:30',NULL,NULL,NULL,'system');
INSERT INTO "auditoria_avancada_v2" ("id","tabela","acao","registro_id","dados_anteriores","dados_novos","created_at","usuario_id","ip_address","user_agent","origem") VALUES(5065,'modelos_sessao','UPDATE','28','{"id":28,"codigo":"A139-P-VFR/C1","nome":"01/03: VFR CICLO 1","tipo":"Treinamento Inicial","descricao":"Sessão focada em manobras básicas em voo visual e emergências elétricas e de motor, em ambiente diurno VFR com cenário offshore. O objetivo é consolidar controle fino da aeronave, autorrotação completa, dual/single GEN failure, falhas de motor e panes em MGB, preparando a tripulação para situações críticas frequentes na operação offshore.","duracao_estimada":120,"treinamento_id":null,"ordem_no_treinamento":null,"ativo":1,"created_at":"2026-01-11 01:50:31","updated_at":"2026-02-28 01:47:45","deleted_at":null,"tipo_sessao_id":9,"tipo_aeronave":"AW139","codigo_aeronave":"AW139","gera_qualificacao":0,"empresa_id":6,"modelo_aeronave":"AW139"}','{"codigo":"A139-P-VFR/C1","nome":"AW139 - PERIÓDICO - 01/03: VFR CICLO 1","tipo_sessao_id":9,"descricao":"Sessão focada em manobras básicas em voo visual e emergências elétricas e de motor, em ambiente diurno VFR com cenário offshore. O objetivo é consolidar controle fino da aeronave, autorrotação completa, dual/single GEN failure, falhas de motor e panes em MGB, preparando a tripulação para situações críticas frequentes na operação offshore.","duracao_estimada":120,"gera_qualificacao":0}','2026-03-11 00:41:43',NULL,NULL,NULL,'system');
INSERT INTO "auditoria_avancada_v2" ("id","tabela","acao","registro_id","dados_anteriores","dados_novos","created_at","usuario_id","ip_address","user_agent","origem") VALUES(5066,'modelos_sessao','UPDATE','30','{"id":30,"codigo":"A139-P-VFR/C2","nome":"01/03: VFR CICLO 2","tipo":"Treinamento Inicial","descricao":"Sessão VFR combinando operações diurnas e noturnas com ênfase em sistema elétrico, combustível e desligamento de emergência de motor. São treinadas falhas de gerador DC, battery offline, low fuel, double fuel pump failure, EEC failure, engine shutdown de emergência, além de decolagens, pousos e autorrotação.","duracao_estimada":120,"treinamento_id":null,"ordem_no_treinamento":null,"ativo":1,"created_at":"2026-01-11 01:50:31","updated_at":"2026-02-28 01:47:45","deleted_at":null,"tipo_sessao_id":9,"tipo_aeronave":"AW139","codigo_aeronave":"AW139","gera_qualificacao":0,"empresa_id":6,"modelo_aeronave":"AW139"}','{"codigo":"A139-P-VFR/C2","nome":"AW139 - PERIÓDICO - 01/03: VFR CICLO 2","tipo_sessao_id":9,"descricao":"Sessão VFR combinando operações diurnas e noturnas com ênfase em sistema elétrico, combustível e desligamento de emergência de motor. São treinadas falhas de gerador DC, battery offline, low fuel, double fuel pump failure, EEC failure, engine shutdown de emergência, além de decolagens, pousos e autorrotação.","duracao_estimada":120,"gera_qualificacao":0}','2026-03-11 00:41:54',NULL,NULL,NULL,'system');
INSERT INTO "auditoria_avancada_v2" ("id","tabela","acao","registro_id","dados_anteriores","dados_novos","created_at","usuario_id","ip_address","user_agent","origem") VALUES(5067,'modelos_sessao','UPDATE','32','{"id":32,"codigo":"A139-P-VFR/C3","nome":"01/03: VFR CICLO 3","tipo":"Treinamento Inicial","descricao":"Sessão VFR sobre água com foco em falhas de rotor de cauda, controles de voo e aquecimento de baterias, em contexto de operação offshore. O treinamento cobre circuito de tráfego, autorrotação, battery overheat, engine failure offshore, falhas de tail rotor drive/control, binding dos comandos, falhas de MGB e EEC, encerrando com aproximação a heliponto.","duracao_estimada":120,"treinamento_id":null,"ordem_no_treinamento":null,"ativo":1,"created_at":"2026-01-11 01:50:31","updated_at":"2026-02-28 01:47:45","deleted_at":null,"tipo_sessao_id":9,"tipo_aeronave":"AW139","codigo_aeronave":"AW139","gera_qualificacao":0,"empresa_id":6,"modelo_aeronave":"AW139"}','{"codigo":"A139-P-VFR/C3","nome":"AW139 - PERIÓDICO - 01/03: VFR CICLO 3","tipo_sessao_id":9,"descricao":"Sessão VFR sobre água com foco em falhas de rotor de cauda, controles de voo e aquecimento de baterias, em contexto de operação offshore. O treinamento cobre circuito de tráfego, autorrotação, battery overheat, engine failure offshore, falhas de tail rotor drive/control, binding dos comandos, falhas de MGB e EEC, encerrando com aproximação a heliponto.","duracao_estimada":120,"gera_qualificacao":0}','2026-03-11 00:42:02',NULL,NULL,NULL,'system');
