INSERT INTO "empresas_config" ("id","empresa_id","dias_alerta_vencimento","email_notificacoes","webhook_url","timezone","logo_relatorio","cores_tema","modulos_ativos","created_at","updated_at","certificado_logo_url","certificado_template_html","certificado_assinatura_digital","idioma") VALUES(1,1,30,NULL,NULL,'America/Sao_Paulo',NULL,'{"system_settings":{"logoUrl":"/api/assets/logos/empresa-1-cbb70182-c559-4e5a-bbc6-9abf0be694a5.png","appName":"Airtrust","faviconUrl":null,"compactHeader":false,"defaultPageSize":20,"enableAnimations":true}}','["treinamento","compliance","documentos","relatorios"]','2025-12-07 17:29:18','2026-03-03 17:41:41',NULL,replace('<!DOCTYPE html>\n<html lang="pt-BR">\n<head>\n  <meta charset="UTF-8">\n  <style>\n    @import url(''https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700&display=swap'');\n    \n    @page {\n      size: A4;\n      margin: 20mm;\n    }\n    \n    * { margin: 0; padding: 0; box-sizing: border-box; }\n    \n    html, body {\n      width: 210mm;\n      min-height: 297mm;\n    }\n    \n    body {\n      font-family: ''Montserrat'', sans-serif;\n      background: #fff;\n      padding: 30mm 25mm;\n      min-height: 297mm;\n      display: flex;\n      flex-direction: column;\n    }\n    \n    .certificate {\n      width: 100%;\n      flex: 1;\n      display: flex;\n      flex-direction: column;\n      text-align: center;\n      position: relative;\n    }\n    \n    .header {\n      display: flex;\n      justify-content: center;\n      align-items: center;\n      margin-bottom: 25mm;\n      padding-bottom: 10mm;\n      border-bottom: 2px solid #e5e7eb;\n    }\n    \n    .company-logo {\n      max-height: 25mm;\n      max-width: 80mm;\n      object-fit: contain;\n    }\n    \n    .title {\n      font-size: 42px;\n      font-weight: 700;\n      color: #1a1a2e;\n      text-decoration: underline;\n      text-decoration-color: #f97316;\n      text-underline-offset: 8px;\n      margin: 0 0 20mm;\n      letter-spacing: 4px;\n    }\n    \n    .main-text {\n      font-size: 14px;\n      color: #374151;\n      line-height: 2;\n      max-width: 150mm;\n      margin: 0 auto 20mm;\n      text-align: justify;\n      text-align-last: center;\n    }\n    \n    .main-text strong {\n      color: #111827;\n      font-weight: 700;\n    }\n    \n    .modules {\n      display: grid;\n      grid-template-columns: 1fr 1fr;\n      gap: 8px;\n      max-width: 140mm;\n      margin: 15mm auto;\n      text-align: left;\n    }\n    \n    .module-item {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      font-size: 12px;\n      color: #374151;\n    }\n    \n    .module-check {\n      width: 18px;\n      height: 18px;\n      background: #22c55e;\n      border-radius: 50%;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: white;\n      font-size: 11px;\n      flex-shrink: 0;\n    }\n    \n    .signature-section {\n      margin-top: auto;\n      padding-top: 20mm;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n    }\n    \n    .signature-line {\n      font-family: ''Brush Script MT'', cursive;\n      font-size: 28px;\n      color: #1a1a2e;\n      margin-bottom: 5px;\n    }\n    \n    .signature-title {\n      font-size: 11px;\n      color: #6b7280;\n      font-style: italic;\n      padding-top: 5mm;\n      border-top: 1px solid #374151;\n      width: 60mm;\n    }\n    \n    .footer {\n      background: linear-gradient(135deg, #0ea5e9, #3b82f6);\n      color: white;\n      padding: 12px 20px;\n      margin-top: 15mm;\n      font-size: 12px;\n      font-weight: 600;\n      border-radius: 4px;\n    }\n    \n    @media print {\n      body {\n        -webkit-print-color-adjust: exact;\n        print-color-adjust: exact;\n      }\n    }\n  </style>\n</head>\n<body>\n  <div class="certificate">\n    <div class="header">\n      <img src="{{logo_url}}" alt="Logo" class="company-logo" />\n    </div>\n    \n    <h1 class="title">CERTIFICADO</h1>\n    \n    <p class="main-text">\n      Certificamos que <strong>{{nome_funcionario}}</strong>, código ANAC <strong>{{codigo_anac}}</strong>,\n      concluiu com aproveitamento o treinamento <strong>{{codigo_qualificacao}} - {{nome_qualificacao}}</strong>,\n      na modalidade EAD, com carga horária de <strong>{{carga_horaria}}</strong> horas-aula\n      pela {{nome_empresa}}, em <strong>{{data_conclusao}}</strong>.\n    </p>\n    \n    <div class="modules">\n      {{conteudo}}\n    </div>\n    \n    <div class="signature-section">\n      <div class="signature-line">Diretor Geral</div>\n      <div class="signature-title">Diretor Geral</div>\n    </div>\n    \n    <div class="footer">\n      {{codigo_qualificacao}} - {{nome_qualificacao}}\n    </div>\n  </div>\n</body>\n</html>','\n',char(10)),NULL,'pt-BR');
